def find_path(graph, start, goal):
    # Initialize the stack for DFS with the start node
    stack = [(start, [start])]
    while stack:
        (node, path) = stack.pop()
        for next_node in graph[node] - set(path):
            if next_node == goal:
                return path + [goal]
            else:
                stack.append((next_node, path + [next_node]))
    return None

